mapper.select:

where del_flag = '0'

    and template_name like concat('%', #{templateName}, '%')


    and template_type = #{templateType}


    and subject_table = #{subjectTable}

order by template_type desc, id asc

mapper.update:
update proj_report_template
template_name = #{templateName}, template_type = #{templateType}, subject_table = #{subjectTable}, source_template_id = #{sourceTemplateId}, template_file = #{templateFile}, file_name = #{fileName}, title_row = #{titleRow}, header_row = #{headerRow}, data_start_row = #{dataStartRow}, has_summary_row = #{hasSummaryRow}, default_filter = #{defaultFilter}::jsonb, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where id = #{id}
